IntervalQualityRepairDraft.SmoothCertificate.projected_step_exists {m : ℕ}
  {method : IntervalQualityRepairDraft.Method m} {q : ℝ → ℝ → Fin m → ℝ} {p : ℝ}
  (certificate : IntervalQualityRepairDraft.SmoothCertificate method q p) (n : ℕ) (hn : certificate.threshold ≤ n) :
  ∃ projected,
    method.geometry.Projection n q projected ∧
      ∃ dt, 0 < dt ∧ dt ≤ method.geometry.horizon ∧ method.admitted n dt projected
